<template><main class="wrap"><h2>注文履歴</h2><el-skeleton v-if="loading" :rows="6" animated/><el-empty v-else-if="!orders.length" description="注文履歴はありません"/><el-table v-else :data="orders"><el-table-column prop="orderNo" label="注文番号" min-width="190"/><el-table-column label="注文日時" min-width="180"><template #default="{row}">{{date(row.orderDate||row.createdAt)}}</template></el-table-column><el-table-column label="合計金額" width="140"><template #default="{row}">¥{{money(row.totalAmount)}}</template></el-table-column><el-table-column label="状況" width="120"><template #default="{row}"><el-tag :type="types[row.status]||'info'">{{labels[row.status]||'不明'}}</el-tag></template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button link type="primary" @click="router.push(`/orders/${row.id}`)">詳細</el-button></template></el-table-column></el-table></main></template>
<script setup>import{onMounted,ref}from'vue';import{ElMessage}from'element-plus';import{useRouter}from'vue-router';import{getMyOrders}from'@/api/order';const router=useRouter(),orders=ref([]),loading=ref(false),labels=['未払い','支払い済み','発送済み','完了','キャンセル'],types=['warning','success','primary','success','info'],money=v=>Number(v).toFixed(2),date=v=>v?new Date(v).toLocaleString('ja-JP'):'--';const load=async()=>{loading.value=true;try{orders.value=(await getMyOrders()).data||[]}catch(e){ElMessage.error(e.response?.data?.message||'注文履歴の取得に失敗しました')}finally{loading.value=false}};onMounted(load)</script><style scoped>.wrap{max-width:1100px;margin:auto;padding:24px}</style>
